import React, { useEffect, useRef } from "react";
import { useDispatch, useSelector } from "react-redux";
import { BiUpArrow } from "react-icons/bi";
import styled, { useTheme } from "styled-components";
import { setHideStatus, setPlaying } from "../../app/features/audioPlayer";
import PlayAndInfo from "../SongBlock/PlayAndInfo";

const Wrapper = styled.div`
  position: fixed;
  bottom: 0;
  width: 100%;
  color: white;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  flex-direction: column;
`;

const HideIconWrapper = styled.div`
  background: ${(props) => props.theme.colors.utilities.text};
  display: inline-block;
  padding: 5px;
  border-radius: 300px;
  cursor: pointer;
  margin-bottom: 10px;
`;

const AudioPlayerContainer = styled.div`
  min-height: 130px;
  width: 100%;
  background: ${(props) => props.theme.colors.backgrounds.dark_2};
  border-radius: 2px;
  overflow: hidden;
  visibility: ${(props) => (props.isHidden ? "collapse" : "visible")};
`;

const DurationLineWrapper = styled.div`
  background: rgba(255, 255, 255, 0.5);
  width: 100%;
  height: 2px;
  position: relative;

  &:hover {
    height: 10px;
  }
`;

const DurationLine = styled.div`
  background: white;
  position: absolute;
  top: 0;
  height: 100%;
`;

const ContentWrapper = styled.div`
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 15px;
`;

const Flex = styled.div`
  flex: 33.33%;
`;

const AudioPlayer = () => {
  const theme = useTheme();
  const dispatch = useDispatch();
  const activeAudio = useSelector((state) => state.audioPlayer?.activeAudio);
  const isHidden = useSelector((state) => state.audioPlayer?.isHidden);
  const isPlaying = useSelector((state) => state.audioPlayer?.isPlaying);
  const activeAudioUrl = useSelector(
    (state) => state.audioPlayer?.activeAudio?.url
  );
  const audioElem = useRef();

  const playAudio = () => {
    audioElem.current.play();
  }

  useEffect(() => {
    if (isPlaying) {
      playAudio();
    }
  }, [])

  return (
    <Wrapper>
      <audio ref={audioElem} src={activeAudioUrl} />
      <HideIconWrapper onClick={() => dispatch(setHideStatus(!isHidden))}>
        <BiUpArrow fill={theme.colors.backgrounds.dark} />
      </HideIconWrapper>
      <AudioPlayerContainer isHidden={isHidden}>
        <DurationLineWrapper>
          <DurationLine style={{ width: "50%" }} />
        </DurationLineWrapper>
        <ContentWrapper>
          <p>{isPlaying ? "yes" : "no"}</p>
          <Flex>
            {activeAudio ? (
              <PlayAndInfo
                onPress={(value) => dispatch(setPlaying(value))}
                isPlaying={isPlaying}
                name={activeAudio.title}
              />
            ) : null}
          </Flex>
          <Flex>2</Flex>
          <Flex></Flex>
        </ContentWrapper>
      </AudioPlayerContainer>
    </Wrapper>
  );
};

export default AudioPlayer;
